// ─── Antardasha theme and prediction generators ───────────────────────────────

interface AnterPredictionContent {
  theme: string;
  detailedPrediction: string;
  keyFocus: string[];
  bestOpportunity: string;
  caution: string;
}

function buildAntarPrediction(
  mahaLord: string,
  antarLord: string,
  rashiName: string,
  lagnaSign: string
): AnterPredictionContent {
  // Thematic keywords per planet pair
  const planetKeywords: Record<string, string[]> = {
    Sun:     ['authority', 'recognition', 'government', 'career prominence', 'solar confidence'],
    Moon:    ['emotional wellbeing', 'public popularity', 'family', 'mother', 'intuition'],
    Mars:    ['initiative', 'courage', 'physical vitality', 'competition', 'real estate'],
    Mercury: ['communication', 'business', 'education', 'writing', 'analytical intelligence'],
    Jupiter: ['wisdom', 'expansion', 'dharma', 'higher education', 'spiritual grace'],
    Venus:   ['creativity', 'romance', 'financial gains', 'beauty', 'partnerships'],
    Saturn:  ['discipline', 'career structure', 'hard work', 'karmic lessons', 'endurance'],
    Rahu:    ['ambition', 'unconventional methods', 'foreign connections', 'innovation', 'obsession'],
    Ketu:    ['spiritual depth', 'detachment', 'past karma', 'hidden knowledge', 'liberation'],
  };

  const mahaKeys = planetKeywords[mahaLord] ?? ['growth', 'expansion', 'karmic themes'];
  const antarKeys = planetKeywords[antarLord] ?? ['activation', 'challenge', 'opportunity'];

  const naturalFriendships: Record<string, string[]> = {
    Sun:     ['Moon', 'Mars', 'Jupiter'],
    Moon:    ['Sun', 'Mercury'],
    Mars:    ['Sun', 'Moon', 'Jupiter'],
    Mercury: ['Sun', 'Venus'],
    Jupiter: ['Sun', 'Moon', 'Mars'],
    Venus:   ['Mercury', 'Saturn'],
    Saturn:  ['Mercury', 'Venus'],
    Rahu:    ['Venus', 'Saturn', 'Mercury'],
    Ketu:    ['Mars', 'Jupiter'],
  };

  const areFriends = naturalFriendships[mahaLord]?.includes(antarLord) ?? false;
  const areEnemies = (mahaLord === 'Sun' && (antarLord === 'Saturn' || antarLord === 'Venus')) ||
                     (mahaLord === 'Saturn' && (antarLord === 'Sun' || antarLord === 'Moon')) ||
                     (mahaLord === 'Moon' && antarLord === 'Saturn');

  const relationshipQuality = areFriends ? 'harmonious and mutually supportive' : areEnemies ? 'challenging but ultimately instructive' : 'neutrally productive';

  const theme = `${mahaLord}–${antarLord}: ${antarKeys[0]} and ${mahaKeys[0]} converge`;

  const detailedPrediction = `During the ${mahaLord} Mahadasha's ${antarLord} Antardasha, your ${rashiName} rasi experiences a ${relationshipQuality} interplay between the energies of these two planetary lords. ${antarLord}'s period activates the themes of ${antarKeys.slice(0, 3).join(', ')} within the broader framework of ${mahaLord}'s overarching ${mahaKeys[0]} narrative. For a native with ${lagnaSign} rising, this antardasha period brings particular emphasis on the house themes that these two planets jointly govern in your chart — their combined influence will be felt most acutely in professional decisions, relationship dynamics, and the management of personal energy and health. ${areFriends ? `The friendly relationship between ${mahaLord} and ${antarLord} creates a period of relative ease and productive momentum in which initiatives launched find natural support.` : areEnemies ? `The challenging relationship between ${mahaLord} and ${antarLord} creates productive friction — this antardasha is most fruitfully understood as a period of karmic acceleration rather than adversity, where obstacles are invitations to develop precisely the qualities that the planetary combination demands.` : `The neutral relationship between ${mahaLord} and ${antarLord} creates a period of workmanlike productivity — neither particularly effortless nor particularly challenging, but consistently responsive to your deliberate initiatives.`} The spiritual dimension of this antardasha asks you to consciously integrate the lessons of both planetary lords into a unified understanding of your current life chapter.`;

  const keyFocus = [
    `${antarKeys[0]} through ${mahaLord}'s overarching influence`,
    `${mahaKeys[1] ?? 'personal development'} guided by ${antarLord}'s activation`,
    `${rashiName} rasi themes intensified by planetary interplay`,
    `Health and energy management under combined ${mahaLord}–${antarLord} pressure`,
    `Relationship dynamics reflecting the ${relationshipQuality} planetary relationship`,
  ];

  const bestOpportunity = `The most significant opportunity of this ${mahaLord}–${antarLord} antardasha lies in the convergence of ${mahaKeys[0]} and ${antarKeys[0]} — initiatives that simultaneously honour both planetary natures have the highest chance of producing lasting results. For your ${rashiName} rasi, this is an auspicious time for ${areFriends ? 'bold expansive action in areas where both planets are naturally strong' : 'patient, disciplined work that turns the friction between these planetary energies into productive momentum'}. Timing significant decisions to align with favourable planetary transits of both ${mahaLord} and ${antarLord} over your natal positions maximises the period's potential.`;

  const caution = `The primary caution of the ${mahaLord}–${antarLord} antardasha period is the risk of ${areEnemies ? 'burnout or conflicting inner drives pulling your energies in contradictory directions — maintaining a clear, consciously chosen priority during this period is essential' : 'underestimating the specific demands of this planetary combination by treating it as simply a continuation of the broader Mahadasha theme'}. ${antarLord}'s energy modifies ${mahaLord}'s influence in ways that require specific attention: ${antarKeys[1] ?? 'the secondary themes this planet activates'} deserve proactive management rather than reactive response. For ${rashiName} rasi natives, the body's signals during this period are worth particular monitoring, as the combined planetary influences may manifest first as physical or energetic sensations before appearing as external life events.`;

  return { theme, detailedPrediction, keyFocus, bestOpportunity, caution };
}

// ─── Best/Caution period identifier ──────────────────────────────────────────

function findBestAndCautionPeriods(
  mahaLord: string,
  antardashas: Array<{ planet: string; start: Date; end: Date }>
): { best: string; caution: string } {
  const MAHA_BEST_ANTAR: Record<string, string[]> = {
    Ketu:    ['Jupiter', 'Mars', 'Moon'],
    Venus:   ['Jupiter', 'Mercury', 'Moon', 'Venus'],
    Sun:     ['Jupiter', 'Moon', 'Mars'],
    Moon:    ['Venus', 'Jupiter', 'Mercury'],
    Mars:    ['Jupiter', 'Sun', 'Moon'],
    Rahu:    ['Jupiter', 'Mercury', 'Venus'],
    Jupiter: ['Jupiter', 'Sun', 'Moon', 'Mars'],
    Saturn:  ['Venus', 'Mercury', 'Saturn'],
    Mercury: ['Venus', 'Jupiter', 'Mercury'],
  };

  const MAHA_CAUTION_ANTAR: Record<string, string[]> = {
    Ketu:    ['Saturn', 'Rahu', 'Sun'],
    Venus:   ['Saturn', 'Rahu', 'Ketu'],
    Sun:     ['Saturn', 'Rahu', 'Venus'],
    Moon:    ['Saturn', 'Ketu', 'Rahu'],
    Mars:    ['Saturn', 'Rahu', 'Ketu'],
    Rahu:    ['Saturn', 'Sun', 'Moon'],
    Jupiter: ['Rahu', 'Saturn', 'Ketu'],
    Saturn:  ['Sun', 'Moon', 'Mars', 'Rahu'],
    Mercury: ['Rahu', 'Ketu', 'Saturn'],
  };

  const bestPlanets = MAHA_BEST_ANTAR[mahaLord] ?? ['Jupiter'];
  const cautionPlanets = MAHA_CAUTION_ANTAR[mahaLord] ?? ['Saturn'];

  let bestPeriod = 'The sub-period of ' + (bestPlanets[0] ?? 'Jupiter');
  let cautionPeriod = 'The sub-period of ' + (cautionPlanets[0] ?? 'Saturn');

  for (const antar of antardashas) {
    if (bestPlanets.includes(antar.planet)) {
      const start = antar.start.toLocaleDateString('en-IN', { month: 'long', year: 'numeric' });
      const end = antar.end.toLocaleDateString('en-IN', { month: 'long', year: 'numeric' });
      bestPeriod = `The ${antar.planet} Antardasha (${start} – ${end}) within your ${mahaLord} Mahadasha is your most auspicious window for major life initiatives — career expansion, investments, marriage decisions, or spiritual commitments initiated during this sub-period carry the best planetary support and are most likely to yield lasting positive results.`;
      break;
    }
  }

  for (const antar of antardashas) {
    if (cautionPlanets.includes(antar.planet)) {
      const start = antar.start.toLocaleDateString('en-IN', { month: 'long', year: 'numeric' });
      const end = antar.end.toLocaleDateString('en-IN', { month: 'long', year: 'numeric' });
      cautionPeriod = `The ${antar.planet} Antardasha (${start} – ${end}) within your ${mahaLord} Mahadasha requires the most deliberate caution and proactive preparation — health, professional relationships, and financial decisions made impulsively during this sub-period are most vulnerable to complications. Increased spiritual practice, health monitoring, and conservative decision-making are strongly advised.`;
      break;
    }
  }

  return { best: bestPeriod, caution: cautionPeriod };
}

// ─── Upcoming antardashas extractor ──────────────────────────────────────────

function extractUpcomingAntardashas(
  mahadashas: Array<{ planet: string; start: Date; end: Date; antardashas: Array<{ planet: string; start: Date; end: Date }> }>,
  currentMahadasha: { planet: string; start: Date; end: Date } | null,
  currentAntardasha: { planet: string; start: Date; end: Date } | null,
  rashiName: string,
  lagnaSign: string
): AntardashaPrediction[] {
  if (!currentMahadasha || !currentAntardasha) return [];

  const now = new Date();
  const upcoming: AntardashaPrediction[] = [];
  let found = false;
  let count = 0;
  const LIMIT = 5;

  for (const maha of mahadashas) {
    for (const antar of maha.antardashas) {
      if (!found) {
        // Find the current antardasha
        if (
          antar.planet === currentAntardasha.planet &&
          antar.start >= currentAntardasha.start
        ) {
          found = true;
        }
        continue;
      }

      if (count >= LIMIT) break;

      const content = buildAntarPrediction(maha.planet, antar.planet, rashiName, lagnaSign);
      upcoming.push({
        mahaLord: maha.planet,
        antarLord: antar.planet,
        startDate: antar.start,
        endDate: antar.end,
        theme: content.theme,
        detailedPrediction: content.detailedPrediction,
        keyFocus: content.keyFocus,
        bestOpportunity: content.bestOpportunity,
        caution: content.caution,
      });
      count++;
    }
    if (count >= LIMIT) break;
  }

  return upcoming;
}

function isSamePeriod(
  first: { planet: string; start: Date; end: Date } | null,
  second: { planet: string; start: Date; end: Date } | null
): boolean {
  if (!first || !second) return false;
  return (
    first.planet === second.planet &&
    first.start.getTime() === second.start.getTime() &&
    first.end.getTime() === second.end.getTime()
  );
}

export function generateDashaRoadmap({
  mahadashas,
  currentMahadasha,
  currentAntardasha,
  rashiName,
  lagnaSign,
  untilYear = 2065,
}: {
  mahadashas: Array<{ planet: string; start: Date; end: Date; antardashas: Array<{ planet: string; start: Date; end: Date }> }>;
  currentMahadasha: { planet: string; start: Date; end: Date } | null;
  currentAntardasha: { planet: string; start: Date; end: Date } | null;
  rashiName: string;
  lagnaSign: string;
  untilYear?: number;
}): DashaRoadmapEntry[] {
  const cutoff = new Date(untilYear, 11, 31, 23, 59, 59, 999);
  const roadmap: DashaRoadmapEntry[] = [];
  const now = new Date();

  let includeFromHere = currentMahadasha === null;

  for (const maha of mahadashas) {
    if (!includeFromHere) {
      if (isSamePeriod(maha, currentMahadasha)) {
        includeFromHere = true;
      } else {
        continue;
      }
    }

    for (const antar of maha.antardashas) {
      if (currentAntardasha && isSamePeriod(antar, currentAntardasha) === false) {
        if (isSamePeriod(maha, currentMahadasha) && antar.end.getTime() <= currentAntardasha.start.getTime()) {
          continue;
        }
      }

      if (!currentAntardasha && antar.end.getTime() <= now.getTime()) {
        continue;
      }

      if (antar.start.getTime() > cutoff.getTime()) {
        return roadmap;
      }

      const content = buildAntarPrediction(maha.planet, antar.planet, rashiName, lagnaSign);
      roadmap.push({
        mahaLord: maha.planet,
        antarLord: antar.planet,
        startDate: antar.start,
        endDate: antar.end,
        theme: content.theme,
        detailedPrediction: content.detailedPrediction,
        keyFocus: content.keyFocus,
        bestOpportunity: content.bestOpportunity,
        caution: content.caution,
        mahaStartDate: maha.start,
        mahaEndDate: maha.end,
        isCurrentAntardasha: isSamePeriod(antar, currentAntardasha),
      });
    }
  }

  return roadmap;
}

// ─── Pratyantar prediction builder ───────────────────────────────────────────

function buildPratyantarPrediction(
  mahaLord: string,
  antarLord: string,
  pratyantarLord: string | null,
  rashiName: string
): string {
  if (!pratyantarLord) {
    return `The current Pratyantardasha information is not available for detailed analysis. In general, the Pratyantardasha lord acts as a fine-grained modifier of the ${mahaLord}–${antarLord} Antardasha themes, accelerating or tempering the combined influence for periods of weeks to a few months at a time. Monitoring the transits of the Pratyantardasha lord over sensitive points in your chart (natal Moon, Lagna, and their lords) provides the most precise timing guidance for decisions during this micro-period.`;
  }

  const transientEffect: Record<string, string> = {
    Sun:     'a period of brief but potentially significant professional recognition or authority-related events',
    Moon:    'heightened emotional sensitivity and public-facing activity',
    Mars:    'accelerated initiative, physical vitality, and the resolution of pending conflicts',
    Mercury: 'busy communication, business transactions, and intellectual engagement',
    Jupiter: 'a fortunate micro-window of grace, good news, and expansive opportunity',
    Venus:   'pleasurable experiences, financial inflows, and harmonious relationship interactions',
    Saturn:  'a period requiring patient discipline and careful management of resources and health',
    Rahu:    'unexpected events, unconventional opportunities, and possible disruptions requiring flexibility',
    Ketu:    'inward reflection, spiritual insight, and possible detachment from worldly concerns',
  };

  const effect = transientEffect[pratyantarLord] ?? 'nuanced modifications to the current dasha themes';

  return `The current ${pratyantarLord} Pratyantardasha within the ${mahaLord}–${antarLord} period brings ${effect} for your ${rashiName} rasi. As the most granular layer of the Vimsottari dasha system, this Pratyantardasha acts as a precise temporal trigger — activating specific dimensions of the broader Antardasha theme in ways that may manifest as concrete events, synchronicities, or inner realisations during its relatively brief duration. For ${rashiName} natives, the ${pratyantarLord}'s natural relationship with both ${mahaLord} and ${antarLord} determines whether this micro-period amplifies, moderates, or introduces friction into the current astrological atmosphere. Remain attentive to the specific dates when the Pratyantardasha lord transits key positions in your natal chart — these are the precise moments when the dasha system's influence crystallises most clearly into visible life events.`;
}

// ─── Main exported function ───────────────────────────────────────────────────

export function generateDashaAnalysis({
  mahadashas,
  currentMahadasha,
  currentAntardasha,
  currentPratyantardasha,
  rashiName,
  lagnaSign,
  nakshatra,
}: {
  mahadashas: Array<{ planet: string; start: Date; end: Date; antardashas: Array<{ planet: string; start: Date; end: Date }> }>;
  currentMahadasha: { planet: string; start: Date; end: Date } | null;
  currentAntardasha: { planet: string; start: Date; end: Date } | null;
  currentPratyantardasha: { planet: string; start: Date; end: Date } | null;
  rashiName: string;
  lagnaSign: string;
  nakshatra: string;
}): DashaAnalysis {

  // ── Current Mahadasha Prediction ─────────────────────────────────────────

  let currentMahadashaPrediction = '';
  if (!currentMahadasha) {
    currentMahadashaPrediction = 'Current Mahadasha data is not available. Please verify your birth data for accurate dasha calculations.';
  } else {
    const mahaLord = currentMahadasha.planet;
    const mahaStart = currentMahadasha.start.toLocaleDateString('en-IN', { month: 'long', year: 'numeric' });
    const mahaEnd   = currentMahadasha.end.toLocaleDateString('en-IN', { month: 'long', year: 'numeric' });
    const basePrediction = MAHADASHA_RASHI_PREDICTIONS[mahaLord]?.[rashiName]
      ?? `The ${mahaLord} Mahadasha brings its characteristic planetary intelligence to bear on your ${rashiName} rasi, activating the house themes that ${mahaLord} governs in your natal chart. This is a significant period requiring conscious alignment with ${mahaLord}'s dharmic qualities for best results.`;

    currentMahadashaPrediction = `You are currently in the ${mahaLord} Mahadasha, which runs from ${mahaStart} to ${mahaEnd} — a period whose planetary signature has been shaping the fundamental direction of your life experience. Born in the nakshatra of ${nakshatra}, your entire chart carries a sensitivity to ${mahaLord}'s transits and periods that makes this Mahadasha particularly resonant with your core karmic curriculum. ${basePrediction} In the early years of this Mahadasha, you may have noticed the emergence of ${mahaLord}-governed themes with a freshness and urgency that felt like the opening of a new life chapter. As the dasha matures, these themes settle into a sustained background note that colours all your experiences — career decisions, relationship choices, health patterns, and spiritual orientation all carry the imprint of ${mahaLord}'s planetary intelligence during this extended period. The closing years of the ${mahaLord} Mahadasha typically bring consolidation, the harvest of seeds planted in earlier years, and a quiet preparation for the very different quality of experience that the subsequent Mahadasha will introduce.`;
  }

  // ── Current Antardasha Prediction ────────────────────────────────────────

  let currentAntardashaPrediction = '';
  if (!currentMahadasha || !currentAntardasha) {
    currentAntardashaPrediction = 'Current Antardasha data is not available. Please verify your birth data for accurate dasha calculations.';
  } else {
    const mahaLord = currentMahadasha.planet;
    const antarLord = currentAntardasha.planet;
    const antarStart = currentAntardasha.start.toLocaleDateString('en-IN', { month: 'long', year: 'numeric' });
    const antarEnd = currentAntardasha.end.toLocaleDateString('en-IN', { month: 'long', year: 'numeric' });

    const naturalFriendships: Record<string, string[]> = {
      Sun: ['Moon', 'Mars', 'Jupiter'], Moon: ['Sun', 'Mercury'], Mars: ['Sun', 'Moon', 'Jupiter'],
      Mercury: ['Sun', 'Venus'], Jupiter: ['Sun', 'Moon', 'Mars'], Venus: ['Mercury', 'Saturn'],
      Saturn: ['Mercury', 'Venus'], Rahu: ['Venus', 'Saturn', 'Mercury'], Ketu: ['Mars', 'Jupiter'],
    };

    const areFriends = naturalFriendships[mahaLord]?.includes(antarLord) ?? false;
    const qualityWord = areFriends ? 'harmoniously supportive' : 'dynamically challenging';

    currentAntardashaPrediction = `Within your ${mahaLord} Mahadasha, you are currently experiencing the ${antarLord} Antardasha — a sub-period running from ${antarStart} to ${antarEnd} that acts as a precise temporal lens focusing ${antarLord}'s specific planetary qualities onto the broader canvas of ${mahaLord}'s overarching influence. The relationship between ${mahaLord} and ${antarLord} in the natural planetary friendship scheme is ${qualityWord}, which means this antardasha period is characterised by ${areFriends ? 'a productive resonance between the two lords, creating windows of relative ease and forward momentum in the areas of life they jointly govern' : 'productive friction that, when consciously navigated, accelerates your karmic learning and strengthens the qualities both lords are asking you to develop'}. For your ${rashiName} rasi with ${lagnaSign} rising, the ${mahaLord}–${antarLord} combination specifically activates the house themes associated with both lords' positions in your natal chart — making this a particularly significant period for decisions related to career, relationships, finances, or spiritual practice that fall under these planetary domains. Health matters governed by both planets deserve proactive attention. The ${nakshatra} nakshatra of your birth adds a further layer of specific sensitivity to this antardasha's themes — pay particular attention to synchronicities and inner knowing during the conjunctions and transits of both ${mahaLord} and ${antarLord} over your natal Moon degree.`;
  }

  // ── Current Pratyantar Prediction ────────────────────────────────────────

  const pratyantarLord = currentPratyantardasha?.planet ?? null;
  const currentPratyantarPrediction = buildPratyantarPrediction(
    currentMahadasha?.planet ?? 'Unknown',
    currentAntardasha?.planet ?? 'Unknown',
    pratyantarLord,
    rashiName
  );

  // ── Upcoming Antardashas ──────────────────────────────────────────────────

  const upcomingAntardashas = extractUpcomingAntardashas(
    mahadashas,
    currentMahadasha,
    currentAntardasha,
    rashiName,
    lagnaSign
  );

  // ── Best & Caution Periods ────────────────────────────────────────────────

  const currentMahaAntar = mahadashas.find(m => m.planet === currentMahadasha?.planet)?.antardashas ?? [];
  const { best: bestPeriodInMaha, caution: cautionPeriodInMaha } = currentMahadasha
    ? findBestAndCautionPeriods(currentMahadasha.planet, currentMahaAntar)
    : { best: 'Best period data unavailable.', caution: 'Caution period data unavailable.' };

  return {
    currentMahadashaPrediction,
    currentAntardashaPrediction,
    currentPratyantarPrediction,
    upcomingAntardashas,
    bestPeriodInMaha,
    cautionPeriodInMaha,
  };
}
